// @ts-check
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';

/** A sidebar group listing every page in a docs folder. */
const folder = (label, directory) => ({ label, items: [{ autogenerate: { directory } }] });

// Autogenerated groups take their label from the folder name ("shader-node"), so groups are
// listed by hand. Maya follows the old site's nav_order.
const mayaSidebar = [
	'maya',
	folder('Setup', 'maya/setup'),
	folder('Getting Started', 'maya/getting-started'),
	{
		label: 'Styles',
		items: [
			'maya/styles',
			folder('Style Library', 'maya/styles/library'),
			'maya/styles/import-export',
		],
	},
	folder('Materials', 'maya/materials'),
	folder('Art-direction Tools', 'maya/art-direction'),
	'maya/toolbox',
	folder('Rendering', 'maya/rendering'),
	{
		label: 'Flair Graph',
		items: [
			'maya/graph',
			'maya/graph/overview',
			'maya/graph/node-graph',
			folder('Shader Node', 'maya/graph/shader-node'),
			'maya/graph/read-node',
			'maya/graph/import-export-node',
			'maya/graph/display-node',
			'maya/graph/presets',
			'maya/graph/hotkeys',
			'maya/graph/expressions',
		],
	},
	'maya/release-log',
	'maya/uninstall',
	'maya/faq',
	folder('API', 'maya/api'),
	'maya/limitations',
];

export default defineConfig({
	site: 'https://docs.flair.graphics',
	integrations: [
		starlight({
			title: 'Flair',
			customCss: ['./src/styles/search.css', './src/styles/content.css'],
			head: [
				{ tag: 'script', attrs: { src: '/scripts/ui-screenshots.js', defer: true } },
				{ tag: 'script', attrs: { src: '/scripts/before-after.js', defer: true } },
			],
			sidebar: [
				{ label: 'Unreal Engine', items: [{ autogenerate: { directory: 'unreal' } }] },
				{ label: 'Maya', items: mayaSidebar },
				folder('Effects', 'effects'),
				folder('Tools', 'tools'),
			],
			components: {
				Head: './src/components/HostHead.astro',
				PageTitle: './src/components/HostPageTitle.astro',
				Sidebar: './src/components/HostSidebar.astro',
			},
		}),
	],
	vite: {
		resolve: {
			alias: [
				{
					// Starlight's Search.astro creates the Pagefind UI internally and never exposes it,
					// so we can't call triggerFilters() from outside. Redirecting this exact import name
					// swaps in a host-aware subclass without copying Starlight's search component.
					// Only the bare name matches: the subclass's deep import and the CSS import pass through.
					find: /^@pagefind\/default-ui$/,
					replacement: fileURLToPath(new URL('./src/lib/host-pagefind-ui.ts', import.meta.url)),
				},
			],
		},
	},
});
